"""Frozen Cohort X analysis. All inputs local; all final artifacts in outputs/."""
import csv
import hashlib
import itertools
import json
from collections import Counter, defaultdict
from decimal import Decimal, InvalidOperation
from pathlib import Path
import sys
import warnings

import numpy as np
import pandas as pd

from statistics_core import (agreement, bh, contrast, finite_median, fractions,
                             medians, observed, self_check, signature_order, u_tests)

OUT = Path("outputs")
DATA = Path("data")
CLAIMS = ["index-muscle-splicing", "cross-site-splicing-agreement",
          "comparator-signature-fraction", "related-signature-fraction"]
MISSING = {"", "NA", "n/a"}


def clean(value):
    if isinstance(value, dict):
        return {str(k): clean(v) for k, v in value.items()}
    if isinstance(value, (list, tuple, np.ndarray)):
        return [clean(v) for v in value]
    if isinstance(value, (np.integer,)):
        return int(value)
    if isinstance(value, (float, np.floating)):
        return float(value) if np.isfinite(value) else None
    if isinstance(value, np.bool_):
        return bool(value)
    return value


def write_json(name, value):
    target = OUT / name
    target.write_text(json.dumps(clean(value), indent=2, allow_nan=False) + "\n")
    if target.stat().st_size > 50000000:
        raise ValueError("Output exceeds size limit: " + str(target))


def read_table(name):
    path = DATA / name
    # QUOTE_NONE preserves the JSON quotes in alias registry cells.
    with path.open() as stream:
        header = stream.readline().rstrip("\r\n").split("\t")
    if len(header) != len(set(header)):
        raise ValueError("Duplicate raw header in " + name)
    frame = pd.read_csv(path, sep="\t", dtype=str, keep_default_na=False,
                        quoting=csv.QUOTE_NONE)
    if list(frame.columns) != header:
        raise ValueError("Header parsing mismatch: " + name)
    return frame


def aliases(namespace):
    frame = read_table(namespace + "-aliases.tsv")
    mapping = {}
    canonical_rows = Counter()
    for row in frame.to_dict("records"):
        if row["namespace"] != namespace:
            raise ValueError("Wrong alias namespace")
        decoded = {key: json.loads(row[key]) for key in ("original", "canonical", "target")}
        if not all(isinstance(v, str) for v in decoded.values()):
            raise ValueError("Non-string alias identifier")
        canonical = decoded["canonical"]
        canonical_rows[canonical] += 1
        for token in decoded.values():
            if token in mapping and mapping[token] != canonical:
                raise ValueError("Ambiguous alias mapping: " + namespace + ":" + token)
            mapping[token] = canonical
    return mapping, {k: n for k, n in canonical_rows.items() if n > 1}


def unique_key(frame, column, mapping):
    mapped = frame[column].map(mapping)
    if mapped.isna().any():
        raise ValueError("Unknown namespace member: " + column)
    if mapped.duplicated().any():
        raise ValueError("Duplicate physical key or equivalent alias: " + column)
    return mapped


def load_inputs(plan):
    problems = []
    maps, collisions = {}, {}
    for namespace in ("event", "sample", "donor"):
        maps[namespace], collisions[namespace] = aliases(namespace)
    for ns, duplicate in collisions.items():
        if duplicate:
            problems.append("Multiple alias rows resolve to the same " + ns + " identity")
    samples, events = read_table("A-samples.tsv"), read_table("A-events.tsv")
    expected_columns = plan["sharedKnobs"]["public_metadata"]["data_tables"]["data/A-samples.tsv"]["columns"]
    if list(samples.columns) != expected_columns:
        raise ValueError("Sample columns differ from locked schema; severity cannot be invented")
    if (samples.isin(["", "NA"])).any().any():
        raise ValueError("Required sample metadata missing")
    samples["sample_key"] = unique_key(samples, "sample", maps["sample"])
    samples["donor_key"] = samples.donor.map(maps["donor"])
    if samples.donor_key.isna().any():
        raise ValueError("Unknown donor identity")
    events["event_key"] = unique_key(events, "event", maps["event"])
    levels = {"group": {"G0", "G1", "G2", "G3"},
              "muscle": {"M%02d" % i for i in range(1, 14)},
              "tissue_class": {"T1", "T2"},
              "site": {"site1", "site2", "site3", "site4"},
              "collection": {"biopsy", "autopsy"}}
    for col, allowed in levels.items():
        if not set(samples[col]) <= allowed:
            raise ValueError("Unknown category: " + col)
    if not set(events.event_type) <= {"SE", "MXE", "ALTSS", "RI"}:
        raise ValueError("Unknown event type")
    group_counts = samples.groupby("donor_key").group.nunique()
    inconsistent = group_counts[group_counts > 1].index.tolist()
    if inconsistent:
        problems.append("Donor identities assigned to multiple disease groups: " + ", ".join(inconsistent))

    frame = read_table("A-psi.tsv")
    event_keys = unique_key(frame, "event", maps["event"])
    if set(event_keys) != set(events.event_key):
        raise ValueError("PSI and annotation event sets differ")
    sample_headers = list(frame.columns[1:])
    header_keys = [maps["sample"].get(s) for s in sample_headers]
    if None in header_keys or len(set(header_keys)) != len(header_keys):
        raise ValueError("Unknown or duplicated sample header")
    if set(header_keys) != set(samples.sample_key):
        raise ValueError("PSI headers and sample metadata differ")
    samples = samples.set_index("sample_key", drop=False).loc[header_keys].reset_index(drop=True)
    events = events.set_index("event_key", drop=False).loc[event_keys].reset_index(drop=True)
    # The PSI file's served event identifier is the report identifier.
    events["event"] = frame.event.to_numpy()
    matrix = np.full((len(frame), len(sample_headers)), np.nan, dtype=float)
    precision_samples, precision_events, precision_examples = {}, set(), []
    nonzero_precision_count, trailing_zero_count = 0, 0
    for j, name in enumerate(sample_headers):
        tokens = frame[name]
        # Bound the parsing cache to one source column. The exact Decimal
        # objects themselves remain in the matrix when extra precision occurs.
        cache = {token: None for token in MISSING}
        token_issues = {}
        column_requires_decimal = False
        for token in tokens.unique():
            if token in cache:
                continue
            try:
                val = Decimal(token)
            except InvalidOperation as error:
                raise ValueError("Nonnumeric PSI token: " + repr(token)) from error
            if not val.is_finite() or not 0 <= val <= 1:
                raise ValueError("PSI outside finite [0,1]: " + repr(token))
            parts = val.as_tuple()
            extra_digits = max(0, -parts.exponent - 2)
            outside_grid = extra_digits > 0 and any(parts.digits[-extra_digits:])
            scaled = Decimal((parts.sign, parts.digits, parts.exponent + 3))
            cache[token] = scaled if outside_grid else int(scaled)
            column_requires_decimal |= outside_grid
            if extra_digits:
                token_issues[token] = "nonzero_extra_precision" if outside_grid else "trailing_zeros"
        if column_requires_decimal and matrix.dtype != object:
            mask = np.isfinite(matrix)
            matrix = matrix.astype(object)
            matrix[~mask] = None
        matrix[:, j] = [cache[token] for token in tokens]
        counts = Counter(tokens)
        issues = {"nonzero_extra_precision": 0, "trailing_zeros": 0}
        for token, issue in token_issues.items():
            issues[issue] += counts[token]
            if len(precision_examples) < 20:
                precision_examples.append({"sample": name, "token": token,
                                           "issue": issue, "n_cells_in_sample": counts[token]})
        if sum(issues.values()):
            precision_samples[name] = issues
            precision_events.update(ids for ids, token in zip(frame.event, tokens) if token in token_issues)
        nonzero_precision_count += issues["nonzero_extra_precision"]
        trailing_zero_count += issues["trailing_zeros"]
    if nonzero_precision_count:
        problems.append("PSI has nonzero precision beyond the declared hundredths in " + str(nonzero_precision_count) + " cells; exact source decimals retained, group medians rounded to three decimals, and U tests preserve raw order and ties")
    if trailing_zero_count:
        problems.append("PSI strings have extra trailing decimal zeros in " + str(trailing_zero_count) + " cells; exact values retained")
    return samples, events, matrix, problems, {"alias_collisions": collisions,
           "inconsistent_donors": inconsistent,
           "precision_issues": {"nonzero_extra_precision_cells": nonzero_precision_count,
                                "trailing_zero_cells": trailing_zero_count,
                                "per_sample": precision_samples,
                                "affected_events": sorted(precision_events),
                                "examples": precision_examples},
           "matrix_sample_headers": sample_headers}


def select(samples, filters):
    mask = np.ones(len(samples), dtype=bool)
    for col, value in filters.items():
        mask &= samples[col].to_numpy() == value
    return np.flatnonzero(mask)


def memberships(samples, plan):
    frozen = plan["sharedKnobs"]["frozen_computations"]
    result = {}
    for name in ("discovery", "replication"):
        conf = frozen[name]
        result[name] = {side: select(samples, dict(conf["filters"], group=group))
                        for side, group in conf["groups"].items()}
    for name in ("comparator", "related"):
        result[name] = {side: select(samples, frozen[name][side + "_filter"])
                        for side in ("case", "control")}
    return result


def cohort_info(samples, groups):
    info = {}
    for name, sides in groups.items():
        info[name] = {}
        for side, ix in sides.items():
            sub = samples.iloc[ix]
            info[name][side] = {"n_samples": len(sub), "n_donors": sub.donor_key.nunique(),
                               "samples": sub["sample"].tolist(), "donors": sorted(set(sub.donor)),
                               "donor_sample_counts": sub.groupby("donor").size().to_dict(),
                               "contexts": sub.groupby(["group", "muscle", "tissue_class", "site", "collection"])
                                              .size().rename("n_samples").reset_index().to_dict("records")}
    return info


def profile_duplicates(matrix, identifiers, by_column=False):
    if matrix.dtype == object:
        rows = matrix.T if by_column else matrix
    else:
        normalized = np.where(np.isfinite(matrix), matrix, -1).astype(np.int16)
        rows = normalized.T if by_column else normalized
    buckets = defaultdict(list)
    for row, identifier in zip(rows, identifiers):
        if matrix.dtype == object:
            # Canonical rational representations avoid false equality from
            # truncation and treat equal decimals with different spelling alike.
            values = []
            for v in row:
                if v is None:
                    values.append("missing")
                else:
                    value = v if isinstance(v, Decimal) else Decimal(int(v))
                    numerator, denominator = value.as_integer_ratio()
                    values.append(str(numerator) + "/" + str(denominator))
            payload = "|".join(values).encode()
        else:
            payload = np.ascontiguousarray(row).tobytes()
        buckets[hashlib.sha256(payload).hexdigest()].append(str(identifier))
    return [members for members in buckets.values() if len(members) > 1]


def integrity(samples, events, matrix, groups, problems, extra):
    repeated = []
    identifiers = set()
    for donor, sub in samples.groupby("donor_key", sort=True):
        if len(sub) > 1:
            identifiers.update(sub.donor.tolist())
            repeated.append({"donor_identity": donor, "donor_identifiers": sorted(set(sub.donor)),
                             "samples": sorted(sub["sample"].tolist()),
                             "tissues": sub[["sample", "muscle", "tissue_class", "site", "collection", "group"]].to_dict("records")})
    overlaps = []
    for a, b in itertools.combinations(groups, 2):
        ia = np.concatenate(list(groups[a].values()))
        ib = np.concatenate(list(groups[b].values()))
        left, right = samples.iloc[ia], samples.iloc[ib]
        shared_sample_keys = set(left.sample_key) & set(right.sample_key)
        shared_donor_keys = set(left.donor_key) & set(right.donor_key)
        shared_samples = sorted(set(samples.loc[samples.sample_key.isin(shared_sample_keys), "sample"]))
        shared_donors = sorted(set(samples.loc[samples.donor_key.isin(shared_donor_keys), "donor"]))
        identifiers.update(shared_samples)
        identifiers.update(shared_donors)
        overlaps.append({"analyses": [a, b], "samples": shared_samples, "donors": shared_donors})
    same_sample_profiles = profile_duplicates(matrix, samples["sample"], True)
    same_event_profiles = profile_duplicates(matrix, events.event)
    # Identical profiles alone do not establish duplicate biological identity.
    audit = {"repeated_donors": repeated, "analysis_overlaps": overlaps,
             "identical_sample_profiles": same_sample_profiles,
             "identical_event_profiles": same_event_profiles,
             "identical_profile_interpretation": "Exact equality including missingness is not proof of duplicate biological identity.",
             "missingness": {"total_cells": matrix.size, "missing_cells": int((~observed(matrix)).sum()),
                             "per_sample": dict(zip(samples["sample"], (~observed(matrix)).sum(axis=0).tolist()))},
             **extra}
    report = {"duplicated_or_overlapping_units": sorted(identifiers),
              "other_data_quality_problems": problems,
              "units_of_analysis": "Tissue samples for group medians and Mann-Whitney U tests; donors are independent biological units. Splicing events, which may be correlated, are the units of cross-event correlation, rankings and fraction summaries."}
    return report, audit


def scope_decisions(samples, groups, inconsistent_donors):
    verdicts, reasons = {}, {}
    discovery_donors = set(samples.iloc[np.concatenate(list(groups["discovery"].values()))].donor_key)
    for name, sides in groups.items():
        why = []
        case, control = (samples.iloc[sides[s]] for s in ("case", "control"))
        for side, sub in (("case", case), ("control", control)):
            if sub.donor_key.nunique() < 2:
                why.append(side + " has fewer than two independent donors")
            if sub.donor_key.duplicated().any():
                why.append(side + " contains repeated donor tissues in the unadjusted sample-level comparison")
        if set(case.donor_key) & set(control.donor_key):
            why.append("Case and control donor identities overlap")
        if (set(case.donor_key) | set(control.donor_key)) & set(inconsistent_donors):
            why.append("Disease labels are inconsistent within contributing donors")
        for col in ("site", "muscle", "tissue_class", "collection"):
            if len(case) and len(control) and not (set(case[col]) & set(control[col])):
                why.append("Group is completely separated by " + col)
        context = ["site", "muscle", "tissue_class", "collection"]
        if len(case) and len(control):
            left = set(case[context].itertuples(index=False, name=None))
            right = set(control[context].itertuples(index=False, name=None))
            if not (left & right):
                why.append("No shared site/muscle/tissue/collection context")
        if name == "replication":
            for side, sub in (("case", case), ("control", control)):
                if len(set(sub.donor_key) - discovery_donors) < 2:
                    why.append(side + " has fewer than two replication donors independent of discovery")
        verdicts[name] = "sample-only" if why else "generalisable"
        reasons[name] = why or ["Both groups have independent donor replication in shared sampling contexts; scope is limited to represented contexts."]
    return verdicts, reasons


def event_table(events, result, prefix=""):
    frame = pd.DataFrame({"event": events})
    for key in ("case_n", "control_n", "keep"):
        frame[prefix + key] = result[key]
    for key in ("case_median", "control_median", "delta"):
        frame[prefix + key] = result[key] / 1000
    return frame


def bootstrap(matrix, samples, groups, original):
    """Resample disease-stratified donors jointly, preserving shared controls."""
    seed, iterations = 20261013, 2000
    rng = np.random.default_rng(seed)
    names = ["spearman_rho", "magnitude_ratio", "comparator_median_f", "related_median_f"]
    draws = {name: [] for name in names}
    required = {"spearman_rho": ["discovery", "replication"],
                "magnitude_ratio": ["discovery", "replication"],
                "comparator_median_f": ["discovery", "comparator"],
                "related_median_f": ["discovery", "related"]}
    reasons = {}
    for target, analyses in required.items():
        for name in analyses:
            for side, ix in groups[name].items():
                if samples.iloc[ix].donor_key.nunique() < 2:
                    reasons[target] = "Fewer than two independent donors in " + name + "/" + side
        if len(matrix) == 0:
            reasons[target] = "No discovery-signature events"
    inconsistent = samples.groupby("donor_key").group.nunique()
    if (inconsistent > 1).any():
        for target in names:
            reasons[target] = "Donor assigned to multiple disease strata"
    donors_by_group = {g: sorted(sub.donor_key.unique()) for g, sub in samples.groupby("group")}
    donor_indices = {donor: np.flatnonzero(samples.donor_key.to_numpy() == donor)
                     for donor in samples.donor_key.unique()}
    masks = {name: {side: np.isin(np.arange(len(samples)), ix) for side, ix in sides.items()}
             for name, sides in groups.items()}
    if len(reasons) < len(names):
        for iteration in range(iterations):
            selected = []
            for donors in donors_by_group.values():
                for donor in rng.choice(donors, size=len(donors), replace=True):
                    selected.extend(donor_indices[donor])
            selected = np.asarray(selected, dtype=int)
            resampled = {name: {side: selected[mask[selected]] for side, mask in sides.items()}
                         for name, sides in masks.items()}
            d = contrast(matrix, **resampled["discovery"])
            if "spearman_rho" not in reasons or "magnitude_ratio" not in reasons:
                r = contrast(matrix, **resampled["replication"])
                fixed = original["replication"]["keep"]
                # Each point is evaluated on the fixed original eligible set;
                # loss of eligibility in a resample makes that target undefined.
                if fixed.any() and np.all(d["keep"][fixed] & r["keep"][fixed]):
                    a = agreement(d["delta"][fixed], r["delta"][fixed])
                    for target in ("spearman_rho", "magnitude_ratio"):
                        if a[target] is not None:
                            draws[target].append(a[target])
            for name in ("comparator", "related"):
                target = name + "_median_f"
                if target in reasons:
                    continue
                c = contrast(matrix, **resampled[name])
                fixed = original[name]["keep"]
                if fixed.any() and np.all(d["keep"][fixed] & c["keep"][fixed] & (d["delta"][fixed] != 0)):
                    value = finite_median(fractions(c["delta"][fixed], d["delta"][fixed]), 10000)
                    if value is not None:
                        draws[target].append(value)
            if (iteration + 1) % 500 == 0:
                print("Donor bootstrap", iteration + 1, "of", iterations, flush=True)
    diagnostic = {}
    for target in names:
        values = np.asarray(draws[target])
        block = {"method": "Disease-stratified donor-cluster percentile bootstrap, conditional on frozen signature and eligible event sets",
                 "seed": seed, "requested_replicates": iterations, "defined_replicates": len(values),
                 "registered_decision_interval": False}
        if target in reasons:
            block["not_estimable_reason"] = reasons[target]
        elif len(values) < .95 * iterations:
            block["not_estimable_reason"] = "Fewer than 95% of resamples define the target on its fixed event set"
        else:
            block["percentile_95_interval"] = np.quantile(values, [.025, .975]).tolist()
            block["bootstrap_se"] = float(np.std(values, ddof=1))
        diagnostic[target] = block
    return diagnostic


def donor_aggregate(matrix, samples, ix):
    donors = sorted(samples.iloc[ix].donor_key.unique())
    columns = [medians(matrix[:, [j for j in ix if samples.iloc[j].donor_key == donor]]) for donor in donors]
    return np.column_stack(columns) if columns else np.empty((len(matrix), 0))


def sensitivity(matrix, events, samples, groups, signature, disc, contrasts):
    audit = {}
    donor_deltas = {}
    for name, sides in groups.items():
        repeated = any(samples.iloc[ix].donor_key.duplicated().any() for ix in sides.values())
        if not repeated:
            donor_deltas[name] = disc["delta"][signature] if name == "discovery" else contrasts[name]["delta"]
            continue
        ix_events = np.arange(len(matrix)) if name == "discovery" else signature
        subset = matrix[ix_events]
        a = donor_aggregate(subset, samples, sides["case"])
        b = donor_aggregate(subset, samples, sides["control"])
        merged = np.concatenate((a, b), axis=1)
        case, control = np.arange(a.shape[1]), np.arange(a.shape[1], merged.shape[1])
        result = contrast(merged, case, control)
        result_frame = event_table(events.event.to_numpy()[ix_events], result)
        block = {"method": "Within-donor median over qualifying tissues followed by group comparison", "n_case_donors": a.shape[1], "n_control_donors": b.shape[1]}
        if name == "discovery":
            u, p, q = u_tests(merged, case, control, result["keep"])
            rank = signature_order(events.event.to_numpy(), result["delta"], p, q)
            result_frame["U"], result_frame["p"], result_frame["q"] = u, p, q
            block["n_signature"] = len(rank)
            donor_deltas[name] = result["delta"][signature]
        else:
            donor_deltas[name] = result["delta"]
        path = "sensitivity-" + name + ".tsv"
        result_frame.to_csv(OUT / path, sep="\t", index=False, na_rep="NA")
        block["eventwise_results"] = "outputs/" + path
        audit[name] = block
    for name in ("comparator", "related"):
        if name in audit:
            audit[name]["median_f"] = finite_median(fractions(donor_deltas[name], donor_deltas["discovery"]), 10000)
    if "discovery" in audit or "replication" in audit:
        audit["donor_level_agreement"] = agreement(donor_deltas["discovery"], donor_deltas["replication"])
    disc_donors = set(samples.iloc[np.concatenate(list(groups["discovery"].values()))].donor_key)
    rep_donors = set(samples.iloc[np.concatenate(list(groups["replication"].values()))].donor_key)
    overlap = disc_donors & rep_donors
    if overlap:
        reduced = {side: np.array([i for i in ix if samples.iloc[i].donor_key not in overlap], dtype=int)
                   for side, ix in groups["replication"].items()}
        result = contrast(matrix[signature], **reduced)
        audit["replication_excluding_discovery_donors"] = {
            "excluded_donor_identities": sorted(overlap),
            "agreement": agreement(disc["delta"][signature], result["delta"]),
            "remaining_counts": {side: len(ix) for side, ix in reduced.items()}}
    return audit


def main():
    OUT.mkdir(exist_ok=True)
    Path("tmp").mkdir(exist_ok=True)
    self_check()
    if len(sys.argv) > 1 and sys.argv[1] == "--self-check":
        print("Scientific boundary checks passed")
        return
    plan = json.loads(Path("plan.json").read_text())
    if set(c["id"] for c in plan["claims"]) != set(CLAIMS):
        raise ValueError("Unexpected locked scientific claim IDs")
    print("Reading local served tables", flush=True)
    samples, events, matrix, problems, extra = load_inputs(plan)
    groups = memberships(samples, plan)
    report_integrity, audit = integrity(samples, events, matrix, groups, problems, extra)
    audit["input_shapes"] = {"A-psi.tsv": {"events": len(events), "samples": len(samples)},
                             "A-events.tsv": {"rows": len(events)},
                             "A-samples.tsv": {"rows": len(samples), "unique_donors": samples.donor_key.nunique()}}
    audit["cohorts"] = cohort_info(samples, groups)
    scope, audit["scope_reasons"] = scope_decisions(samples, groups, extra["inconsistent_donors"])
    print("Computing discovery on", len(events), "events", flush=True)
    disc = contrast(matrix, **groups["discovery"])
    u, p, q = u_tests(matrix, **groups["discovery"], keep=disc["keep"])
    ids = events.event.to_numpy()
    signature = signature_order(ids, disc["delta"], p, q)
    top = signature[:50]
    discovery_frame = event_table(ids, disc)
    discovery_frame["event_type"] = events.event_type
    discovery_frame["U"], discovery_frame["p"], discovery_frame["q"] = u, p, q
    discovery_frame["signature"] = np.isin(np.arange(len(events)), signature)
    discovery_frame.to_csv(OUT / "discovery-events.tsv", sep="\t", index=False, na_rep="NA")
    discovery_frame.iloc[signature].to_csv(OUT / "signature.tsv", sep="\t", index=False, na_rep="NA")
    subset = matrix[signature]
    contrasts = {name: contrast(subset, **groups[name]) for name in ("replication", "comparator", "related")}
    a = agreement(disc["delta"][signature], contrasts["replication"]["delta"])
    fs = {name: fractions(contrasts[name]["delta"], disc["delta"][signature]) for name in ("comparator", "related")}
    core = np.isfinite(fs["comparator"]) & (fs["comparator"] < 2500)
    n_f = int(np.isfinite(fs["comparator"]).sum())
    task = {"discovery": {"n_signature": len(signature),
                           "top50_increased": ids[top[disc["delta"][top] > 0]].tolist(),
                           "top50_decreased": ids[top[disc["delta"][top] < 0]].tolist()},
            "replication": {key: a[key] for key in ("spearman_rho", "magnitude_ratio", "verdict")},
            "comparator": {"median_f": finite_median(fs["comparator"], 10000),
                           "specific_core": ids[signature[core]].tolist(),
                           "specificity": "specific" if 2 * int(core.sum()) > n_f else "not-specific"},
            "related": {"median_f": finite_median(fs["related"], 10000)},
            "severity": {"verdict": "not-testable"}, "scope": scope, "integrity": report_integrity}
    write_json("task-results.json", task)
    # Code-phase rule confines final output to outputs/. No root-level writes.
    write_json("report.json", task)
    for name, result in contrasts.items():
        frame = event_table(ids[signature], result)
        frame["dPSI_disc"] = disc["delta"][signature] / 1000
        if name in fs:
            frame["f"] = fs[name] / 10000
        frame.to_csv(OUT / (name + "-events.tsv"), sep="\t", index=False, na_rep="NA")
    audit["replication"] = a
    audit["eligible_event_counts"] = {"discovery": int(disc["keep"].sum()),
                                      **{name: int(c["keep"].sum()) for name, c in contrasts.items()}}
    audit["comparator_all_samples_T1"] = bool((samples.iloc[groups["comparator"]["case"]].tissue_class == "T1").all())
    audit["severity"] = {"available_columns": list(samples.columns[:7]), "reason": "No donor-linked clinical severity measurement in the served source schema"}
    audit["undefined_statistics"] = []
    for group, fields in {"replication": ["spearman_rho", "magnitude_ratio"], "comparator": ["median_f"], "related": ["median_f"]}.items():
        for field in fields:
            if task[group][field] is None:
                audit["undefined_statistics"].append({"field": "/" + group + "/" + field,
                    "reason": "No eligible events or constant/insufficient input for the requested statistic"})
    print("Computed", len(signature), "signature events; running frozen uncertainty and sensitivity", flush=True)
    diagnostics = bootstrap(subset, samples, groups, contrasts)
    audit["sensitivity"] = sensitivity(matrix, events, samples, groups, signature, disc, contrasts)
    write_json("diagnostics.json", diagnostics)

    # No scalar is substituted for the locked vector-valued discovery estimand.
    # The incompatible V7 scalar contract is recorded and appealed explicitly.
    discovery_donors = set(samples.iloc[np.concatenate(list(groups["discovery"].values()))].donor_key)
    primary = {"claims": {CLAIMS[0]: {"n_units": len(discovery_donors)}}}
    primary_details = {CLAIMS[0]: {"status": "exploratory",
                        "estimate_artifact": "outputs/discovery-events.tsv",
                        "reason_scalar_estimate_omitted": "Locked estimand is a vector of eventwise median differences; scalar substitution prohibited by locked plan"}}
    targets = {CLAIMS[1]: (a["spearman_rho"], "spearman_rho", ["discovery", "replication"]),
               CLAIMS[2]: (task["comparator"]["median_f"], "comparator_median_f", ["discovery", "comparator"]),
               CLAIMS[3]: (task["related"]["median_f"], "related_median_f", ["discovery", "related"])}
    for claim_id, (estimate, diagnostic, analyses) in targets.items():
        index = np.concatenate([ix for name in analyses for ix in groups[name].values()])
        block = {"n_units": int(samples.iloc[index].donor_key.nunique())}
        if estimate is not None:
            block["estimate"] = estimate
        if claim_id == CLAIMS[1] and a["p"] is not None:
            block["p"] = a["p"]
        if "bootstrap_se" in diagnostics[diagnostic]:
            block["se"] = diagnostics[diagnostic]["bootstrap_se"]
        primary["claims"][claim_id] = block
        primary_details[claim_id] = {"status": "exploratory", "uncertainty": "outputs/diagnostics.json#" + diagnostic,
                                    "n_units_definition": "Unique underlying donors across contributing comparisons; event count is recorded separately",
                                    "reason_ci_omitted": "No registered decision interval; conditional donor-bootstrap interval is diagnostic only"}
        if estimate is None:
            primary_details[claim_id]["reason_estimate_omitted"] = "Requested estimand undefined on this dataset; no placeholder substituted"
        if claim_id != CLAIMS[1]:
            primary_details[claim_id]["reason_p_omitted"] = "Descriptive estimate; no hypothesis test requested"
    write_json("primary.json", primary)
    write_json("primary-details.json", primary_details)
    audit["provenance"] = {"software_versions_status": "Not collected: runtime version metadata access was rejected by the code-policy checker; no alternative lookup attempted.",
                           "plan_sha256": hashlib.sha256(Path("plan.json").read_bytes()).hexdigest(),
                           "input_sha256": {path.name: hashlib.sha256(path.read_bytes()).hexdigest() for path in sorted(DATA.glob("*.tsv"))}}
    audit["output_contract_mismatches"] = [
        "Discovery is a locked eventwise vector, but V7 requires one numeric estimate per claim. The full vector is preserved; no dummy scalar is emitted.",
        "The task requests root report.json but code-phase rules allow final writes only under outputs; identical task answers are in outputs/report.json and outputs/task-results.json."]
    write_json("audit.json", audit)
    # Invariants over computed results.
    assert len(task["discovery"]["top50_increased"]) + len(task["discovery"]["top50_decreased"]) == min(50, len(signature))
    for values in (task["discovery"]["top50_increased"], task["discovery"]["top50_decreased"], task["comparator"]["specific_core"]):
        assert len(values) == len(set(values)) and set(values) <= set(ids)
    assert json.loads((OUT / "report.json").read_text()) == json.loads((OUT / "task-results.json").read_text())
    ordered_p = np.argsort(p[disc["keep"]])
    assert np.all(np.diff(q[disc["keep"]][ordered_p]) >= -1e-15)
    for path in OUT.iterdir():
        assert path.is_file() and not path.is_symlink() and path.stat().st_size <= 50000000
    print("Analysis complete; task answers and audit written under outputs/", flush=True)


if __name__ == "__main__":
    try:
        main()
    except Exception as error:
        OUT.mkdir(exist_ok=True)
        write_json("execution-error.json", {"error_type": type(error).__name__, "message": str(error)})
        raise
